<?php

namespace App\Http\Controllers;

use App\Models\Patron;
use App\Support\PatronImportReader;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Throwable;

/**
 * Admin / librarian: add many patrons at once from an Excel (.xlsx) or CSV sheet.
 *
 * - Additive only: an ID number that already exists is skipped, never overwritten.
 * - The upload is read in memory and discarded. Nothing is saved to storage.
 * - No file is generated by the system (the sample template is a static file).
 */
class PatronImportController extends Controller
{
    private const MAX_ROWS = 5000;

    /** Header text (letters and digits only, lowercase) -> field. */
    private const HEADERS = [
        'idnumber' => 'id_number', 'id' => 'id_number', 'idno' => 'id_number', 'studentid' => 'id_number',
        'patronid' => 'id_number', 'studentnumber' => 'id_number', 'studnum' => 'id_number', 'studno' => 'id_number',
        'studentno' => 'id_number', 'learnerid' => 'id_number', 'lrn' => 'id_number',
        'name' => 'name', 'fullname' => 'name', 'studentname' => 'name', 'studname' => 'name', 'learnername' => 'name',
        'type' => 'patron_type', 'patrontype' => 'patron_type',
        'email' => 'email', 'emailaddress' => 'email',
        'contactno' => 'contact_no', 'contact' => 'contact_no', 'contactnumber' => 'contact_no',
        'phone' => 'contact_no', 'mobile' => 'contact_no', 'mobileno' => 'contact_no',
        'status' => 'status',
    ];

    public function create()
    {
        abort_unless(auth()->user()->canManage(), 403);

        return view('patrons.import');
    }

    public function store(Request $request)
    {
        abort_unless($request->user()->canManage(), 403);

        $request->validate([
            'file' => ['required', 'file', 'max:2048'],
        ], [
            'file.max' => 'The file is too big (2 MB max). Split it into smaller sheets.',
        ]);

        $extension = strtolower($request->file('file')->getClientOriginalExtension());

        if (! in_array($extension, ['xlsx', 'csv', 'txt'], true)) {
            return back()->withErrors(['file' => 'Please upload an Excel file (.xlsx) or a CSV file. Old .xls files: open and Save As .xlsx first.']);
        }

        try {
            $rows = PatronImportReader::rows($request->file('file')->getRealPath(), $extension);
        } catch (Throwable $e) {
            return back()->withErrors(['file' => $e->getMessage()]);
        }

        // First non-empty row is the header.
        $header = null;
        $body = [];

        foreach ($rows as $row) {
            if (collect($row['cells'])->filter(fn ($v) => $v !== '')->isEmpty()) {
                continue;
            }

            if ($header === null) {
                $header = $row['cells'];
                continue;
            }

            $body[] = $row;
        }

        if ($header === null) {
            return back()->withErrors(['file' => 'The file is empty.']);
        }

        $map = [];
        foreach ($header as $index => $text) {
            $key = preg_replace('/[^a-z0-9]/', '', strtolower((string) $text));

            if (isset(self::HEADERS[$key]) && ! in_array(self::HEADERS[$key], $map, true)) {
                $map[$index] = self::HEADERS[$key];
            }
        }

        if (! in_array('id_number', $map, true) || ! in_array('name', $map, true)) {
            return back()->withErrors(['file' => 'The first row must have the headings "ID Number" and "Name" (optional: Type, Email, Contact No, Status). Use the sample template.']);
        }

        if (count($body) > self::MAX_ROWS) {
            return back()->withErrors(['file' => 'Too many rows (' . count($body) . '). The limit is ' . self::MAX_ROWS . ' per file. Split the sheet.']);
        }

        $existing = Patron::pluck('id_number')->map(fn ($v) => strtolower((string) $v))->flip()->all();
        $created = 0;
        $skipped = [];

        DB::transaction(function () use ($body, $map, &$existing, &$created, &$skipped) {
            foreach ($body as $row) {
                $data = [];
                foreach ($map as $index => $field) {
                    $data[$field] = trim((string) ($row['cells'][$index] ?? ''));
                }

                $error = $this->validateRow($data, $existing);

                if ($error) {
                    $skipped[] = ['row' => $row['row'], 'id' => $data['id_number'] ?? '', 'name' => $data['name'] ?? '', 'reason' => $error];
                    continue;
                }

                Patron::create([
                    'id_number'   => $data['id_number'],
                    'name'        => $data['name'],
                    'patron_type' => $data['patron_type'],
                    'email'       => ($data['email'] ?? '') !== '' ? $data['email'] : null,
                    'contact_no'  => ($data['contact_no'] ?? '') !== '' ? $data['contact_no'] : null,
                    'status'      => $data['status'],
                ]);

                $existing[strtolower($data['id_number'])] = true;
                $created++;
            }
        });

        return redirect()->route('patrons.import')->with('import_result', [
            'created' => $created,
            'skipped' => $skipped,
            'total'   => count($body),
        ]);
    }

    /** Returns an error text, or null when the row is fine. Normalizes type and status in $data. */
    private function validateRow(array &$data, array $existing): ?string
    {
        $id = $data['id_number'] ?? '';
        $name = $data['name'] ?? '';

        if ($id === '' || $name === '') {
            return 'ID number and name are both required.';
        }

        if (mb_strlen($id) > 255 || mb_strlen($name) > 255) {
            return 'ID number or name is too long.';
        }

        if (isset($existing[strtolower($id)])) {
            return 'This ID number already exists (kept as is).';
        }

        $type = $data['patron_type'] ?? '';
        if ($type === '') {
            $data['patron_type'] = 'Student';
        } else {
            $match = collect(Patron::TYPES)->first(fn ($t) => strcasecmp($t, $type) === 0);

            if (! $match) {
                return 'Type "' . $type . '" is not valid. Use: ' . implode(', ', Patron::TYPES) . '.';
            }

            $data['patron_type'] = $match;
        }

        $email = $data['email'] ?? '';
        if ($email !== '' && ! filter_var($email, FILTER_VALIDATE_EMAIL)) {
            return 'Email "' . $email . '" is not valid.';
        }

        if (mb_strlen($data['contact_no'] ?? '') > 50) {
            return 'Contact number is too long.';
        }

        $data['status'] = strcasecmp($data['status'] ?? '', 'inactive') === 0 ? 'inactive' : 'active';

        return null;
    }
}
